let sel = $input.first().json.output[0].content[0].text;
if (typeof sel === 'string') {
  sel = JSON.parse(sel.replace(/^```json\s*/i, '').replace(/```\s*$/, ''));
}
if (!sel.topic || !Array.isArray(sel.knowledge_tags) || !Array.isArray(sel.selected_sources) || sel.selected_sources.length < 2) {
  throw new Error('選題輸出格式不正確：' + JSON.stringify(sel).slice(0, 200));
}
return [{ json: sel }];

const sel = $('解析選題').first().json;
const entries = $input.first().json.entries || [];
if (entries.length === 0) throw new Error('知識庫查無相關條目，請檢查 knowledge_tags');
const recentTitles = $('選題素材').first().json.recentTitles || [];
const prompt = `主題：${sel.topic}
切角：${sel.angle}

外部來源（文末「## 參考資料」須逐篇附上連結）：
${JSON.stringify(sel.selected_sources, null, 1)}

知識庫條目（理論依據，引用論點時標明 source）：
${JSON.stringify(entries, null, 1)}

近期已發文標題（新標題句式不得與其相似）：
${JSON.stringify(recentTitles)}`;
return [{ json: { prompt } }];

